SELECT segment_marketplace_id, segment_id, MAX(segment_name) AS segment_name, MAX(segment_description) AS segment_description, MAX(category_level_1) AS category_level_1, MAX(category_level_2) AS category_level_2, MAX(category_path) AS category_path, BUILT_IN_PARAMETER('TIME_WINDOW_START') AS time_window_start, BUILT_IN_PARAMETER('TIME_WINDOW_END') AS time_window_end FROM segment_metadata WHERE segment_marketplace_id = CUSTOM_PARAMETER('segment_marketplace_id') GROUP BY segment_marketplace_id, segment_id
